import { Effect } from "effect";

import { OAuthProfileStorageError } from "./errors.js";
import type { CodexOAuthSubject } from "./schemas.js";

export const codexOAuthProfileStoragePrefix =
  "bundjil/oauth/v1/provider/codex/profile";

export const codexOAuthRefreshLockStoragePrefix =
  "bundjil/oauth/v1/provider/codex/refresh-lock";

export const codexOAuthProfileSubjectHash = (subject: CodexOAuthSubject) =>
  Effect.tryPromise({
    try: async () => {
      const digest = await globalThis.crypto.subtle.digest(
        "SHA-256",
        new TextEncoder().encode(
          [
            subject.provider,
            subject.principal.type,
            subject.principal.id,
            subject.principal.issuer,
            subject.connectorId,
            subject.installationId,
            subject.profileId,
          ].join("\u001F")
        )
      );

      return Array.from(new Uint8Array(digest), (byte) =>
        byte.toString(16).padStart(2, "0")
      ).join("");
    },
    catch: (cause) =>
      new OAuthProfileStorageError({
        operation: "deriveProfileStorageKey",
        message: "Unable to derive Codex OAuth profile storage key.",
        cause,
      }),
  });

export const codexOAuthProfileStorageKey = Effect.fn(
  "CodexOAuthProfileStorageKey.derive"
)(function* (subject: CodexOAuthSubject) {
  const subjectHash = yield* codexOAuthProfileSubjectHash(subject);

  return `${codexOAuthProfileStoragePrefix}/${subjectHash}`;
});

export const codexOAuthRefreshLockStorageKey = Effect.fn(
  "CodexOAuthRefreshLockStorageKey.derive"
)(function* (subject: CodexOAuthSubject) {
  const subjectHash = yield* codexOAuthProfileSubjectHash(subject);

  return `${codexOAuthRefreshLockStoragePrefix}/${subjectHash}`;
});
import { Context, Effect, Redacted, Schema } from "effect";

import { CodexOAuthProfileCipherError } from "./errors.js";
import type { CodexOAuthProfileCipherFailure } from "./errors.js";
import { CodexOAuthProfileCipherConfigService } from "./profile-cipher.config.js";
import { CodexOAuthProfile, EncryptedCodexOAuthProfileV1 } from "./schemas.js";
import type {
  CodexOAuthProfile as CodexOAuthProfileType,
  EncryptedCodexOAuthProfile,
  EncryptedCodexOAuthProfileV1 as EncryptedCodexOAuthProfileV1Type,
} from "./schemas.js";
import { codexOAuthProfileSubjectHash } from "./storage-keys.js";

const codexOAuthProfileJson = Schema.fromJsonString(CodexOAuthProfile);

const toArrayBuffer = (value: Uint8Array) => {
  const copy = new Uint8Array(value.byteLength);
  copy.set(value);
  return copy.buffer;
};

export interface CodexOAuthProfileCipherShape {
  readonly encrypt: (
    profile: CodexOAuthProfileType
  ) => Effect.Effect<
    EncryptedCodexOAuthProfileV1Type,
    CodexOAuthProfileCipherFailure
  >;
  readonly decrypt: (
    encryptedProfile: EncryptedCodexOAuthProfile
  ) => Effect.Effect<CodexOAuthProfileType, CodexOAuthProfileCipherFailure>;
}

export class CodexOAuthProfileCipher extends Context.Service<
  CodexOAuthProfileCipher,
  CodexOAuthProfileCipherShape
>()("@bundjil/codex-oauth/CodexOAuthProfileCipher") {}

export const makeCodexOAuthProfileCipher = Effect.fn(
  "CodexOAuthProfileCipherLive"
)(function* makeCodexOAuthProfileCipherService(
  crypto: Crypto = globalThis.crypto
) {
  const config = yield* CodexOAuthProfileCipherConfigService;
  const keyMaterial = yield* Schema.decodeUnknownEffect(
    Schema.Uint8ArrayFromBase64
  )(Redacted.value(config.keyMaterial)).pipe(
    Effect.mapError(
      () =>
        new CodexOAuthProfileCipherError({
          operation: "loadKey",
          keyId: config.keyId,
          message: "Codex OAuth profile encryption key material is invalid.",
        })
    )
  );
  const key = yield* Effect.tryPromise({
    try: () =>
      crypto.subtle.importKey(
        "raw",
        toArrayBuffer(keyMaterial),
        config.algorithm,
        false,
        ["encrypt", "decrypt"]
      ),
    catch: () =>
      new CodexOAuthProfileCipherError({
        operation: "loadKey",
        keyId: config.keyId,
        message: "Unable to import the Codex OAuth profile encryption key.",
      }),
  });

  return CodexOAuthProfileCipher.of({
    encrypt: Effect.fn("CodexOAuthProfileCipher.encrypt")(function* (
      profile: CodexOAuthProfileType
    ) {
      const subjectHash = yield* codexOAuthProfileSubjectHash(
        profile.subject
      ).pipe(
        Effect.mapError(
          () =>
            new CodexOAuthProfileCipherError({
              operation: "encrypt",
              keyId: config.keyId,
              message: "Unable to derive the encrypted profile subject hash.",
            })
        )
      );
      const plaintext = yield* Schema.encodeEffect(codexOAuthProfileJson)(
        profile
      ).pipe(
        Effect.mapError(
          () =>
            new CodexOAuthProfileCipherError({
              operation: "encode",
              keyId: config.keyId,
              message:
                "Unable to encode the Codex OAuth profile for encryption.",
            })
        )
      );
      const nonce = yield* Effect.try({
        try: () => crypto.getRandomValues(new Uint8Array(12)),
        catch: () =>
          new CodexOAuthProfileCipherError({
            operation: "encrypt",
            keyId: config.keyId,
            message: "Unable to generate a profile encryption nonce.",
          }),
      });
      const ciphertext = yield* Effect.tryPromise({
        try: () =>
          crypto.subtle.encrypt(
            {
              name: config.algorithm,
              iv: toArrayBuffer(nonce),
              tagLength: 128,
            },
            key,
            new TextEncoder().encode(plaintext)
          ),
        catch: () =>
          new CodexOAuthProfileCipherError({
            operation: "encrypt",
            keyId: config.keyId,
            message: "Unable to encrypt the Codex OAuth profile.",
          }),
      });

      return yield* Schema.decodeUnknownEffect(EncryptedCodexOAuthProfileV1)({
        version: 1,
        algorithm: config.algorithm,
        keyId: config.keyId,
        nonce,
        ciphertext: new Uint8Array(ciphertext),
        subjectHash,
        createdAtEpochMillis: profile.createdAtEpochMillis,
        updatedAtEpochMillis: profile.updatedAtEpochMillis,
      }).pipe(
        Effect.mapError(
          () =>
            new CodexOAuthProfileCipherError({
              operation: "encode",
              keyId: config.keyId,
              message: "Unable to encode the encrypted Codex OAuth profile.",
            })
        )
      );
    }),
    decrypt: Effect.fn("CodexOAuthProfileCipher.decrypt")(function* (
      encryptedProfile: EncryptedCodexOAuthProfile
    ) {
      if (encryptedProfile.version !== 1) {
        return yield* new CodexOAuthProfileCipherError({
          operation: "unsupportedVersion",
          keyId: encryptedProfile.keyId,
          version: encryptedProfile.version,
          message: "The encrypted Codex OAuth profile version is unsupported.",
        });
