import { Schema } from "effect";

import { CodexLocalProfileImportOperation } from "./contracts.js";

export class CodexLocalProfileImportError extends Schema.TaggedErrorClass<CodexLocalProfileImportError>()(
  "CodexLocalProfileImportError",
  {
    operation: CodexLocalProfileImportOperation,
    message: Schema.NonEmptyString,
    cause: Schema.optional(Schema.Defect),
  }
) {}

import { Clock, Context, Effect, Layer, Schema } from "effect";

import { CodexLocalProfileImportError } from "./errors.js";
import type { CodexLocalProfileImportFailure } from "./errors.js";
import { CodexLocalAuthCacheSource } from "./local-auth-cache-source.service.js";
import { CodexLocalProfileImportConfigService } from "./local-profile-import.config.js";
import { CodexProfileStore } from "./profile-store.service.js";
import {
  CodexLocalProfileImportResult,
  CodexOAuthProfile,
} from "./schemas.js";
import type { CodexLocalProfileImportResult as CodexLocalProfileImportResultType } from "./schemas.js";

export interface CodexLocalProfileImportServiceShape {
  readonly importProfile: () => Effect.Effect<
    CodexLocalProfileImportResultType,
    CodexLocalProfileImportFailure
  >;
}

export class CodexLocalProfileImportService extends Context.Service<
  CodexLocalProfileImportService,
  CodexLocalProfileImportServiceShape
>()("@bundjil/codex-oauth/CodexLocalProfileImportService") {}

export const makeCodexLocalProfileImportService = Effect.gen(
  function* makeCodexLocalProfileImportService() {
    const config = yield* CodexLocalProfileImportConfigService;
    const source = yield* CodexLocalAuthCacheSource;
    const profileStore = yield* CodexProfileStore;

    return CodexLocalProfileImportService.of({
      importProfile: Effect.fn("CodexLocalProfileImportService.importProfile")(
        function* importProfile() {
          const cache = yield* source.readCache();
          const refreshedAtEpochMillis = cache.last_refresh.getTime();
          const expiresAtEpochMillis =
            refreshedAtEpochMillis + config.accessTokenTtlMillis;
          const nowEpochMillis = yield* Clock.currentTimeMillis;

          if (
            !Number.isFinite(refreshedAtEpochMillis) ||
            !Number.isFinite(expiresAtEpochMillis) ||
            expiresAtEpochMillis <= nowEpochMillis
          ) {
            return yield* new CodexLocalProfileImportError({
              operation: "validateExpiry",
              message:
                "The local Codex access token is expired or has an invalid refresh timestamp.",
            });
          }

          const profile = yield* Schema.decodeUnknownEffect(CodexOAuthProfile)({
            subject: config.subject,
            accessToken: cache.tokens.access_token,
            expiresAtEpochMillis,
            scopes: [],
            createdAtEpochMillis: nowEpochMillis,
            updatedAtEpochMillis: nowEpochMillis,
            requiresReauthentication: true,
          }).pipe(
            Effect.mapError(
              (cause) =>
                new CodexLocalProfileImportError({
                  operation: "buildProfile",
                  message: "Unable to construct the local Codex access profile.",
                  cause,
                })
            )
          );

          yield* profileStore.putProfile(profile).pipe(
            Effect.mapError(
              (cause) =>
                new CodexLocalProfileImportError({
                  operation: "putProfile",
                  message: "Unable to store the local Codex access profile.",
                  cause,
                })
            )
          );

          return yield* Schema.decodeUnknownEffect(
            CodexLocalProfileImportResult
          )({
            profileId: config.subject.profileId,
            mode: cache.auth_mode,
            requiresReauthentication: true,
            expiryStatus: "valid",
            encryptedStore: "stored",
          }).pipe(
            Effect.mapError(
              (cause) =>
                new CodexLocalProfileImportError({
                  operation: "encodeResult",
                  message: "Unable to encode the local Codex import result.",
                  cause,
                })
            )
          );
        }
      ),
    });
  }
).pipe(Effect.withSpan("CodexLocalProfileImportServiceLive"));

export const CodexLocalProfileImportServiceLive = Layer.effect(
  CodexLocalProfileImportService,
  makeCodexLocalProfileImportService
);

export const importCodexLocalProfile = Effect.gen(
  function* importCodexLocalProfileOperation() {
    const service = yield* CodexLocalProfileImportService;

    return yield* service.importProfile();
  }
);

import { Context, Effect, Layer, Schema } from "effect";
import { readFile } from "node:fs/promises";

import { CodexLocalProfileImportError } from "./errors.js";
import { CodexLocalProfileImportConfigService } from "./local-profile-import.config.js";
import { CodexCliAuthCache } from "./schemas.js";
import type { CodexCliAuthCache as CodexCliAuthCacheType } from "./schemas.js";

const codexCliAuthCacheJson = Schema.fromJsonString(CodexCliAuthCache);

const decodeCodexCliAuthCache = (input: unknown) =>
  Schema.decodeUnknownEffect(CodexCliAuthCache)(input).pipe(
    Effect.mapError(
      (cause) =>
        new CodexLocalProfileImportError({
          operation: "decodeCache",
          message: "Unable to decode the local Codex auth cache.",
          cause,
        })
    )
  );

export interface CodexLocalAuthCacheSourceShape {
  readonly readCache: () => Effect.Effect<
    CodexCliAuthCacheType,
    CodexLocalProfileImportError
  >;
}

export class CodexLocalAuthCacheSource extends Context.Service<
  CodexLocalAuthCacheSource,
  CodexLocalAuthCacheSourceShape
>()("@bundjil/codex-oauth/CodexLocalAuthCacheSource") {}

export const CodexLocalAuthCacheSourceLive = Layer.effect(
  CodexLocalAuthCacheSource,
  Effect.gen(function* makeCodexLocalAuthCacheSource() {
    const config = yield* CodexLocalProfileImportConfigService;

    return CodexLocalAuthCacheSource.of({
      readCache: Effect.fn("CodexLocalAuthCacheSource.readCache")(
        function* readCache() {
          const content = yield* Effect.tryPromise({
            try: () => readFile(config.localAuthFile, "utf8"),
            catch: (cause) =>
              new CodexLocalProfileImportError({
                operation: "readCache",
                message: "Unable to read the local Codex auth cache.",
                cause,
              }),
          });

          return yield* Schema.decodeUnknownEffect(codexCliAuthCacheJson)(
            content
          ).pipe(
            Effect.mapError(
              (cause) =>
                new CodexLocalProfileImportError({
                  operation: "decodeCache",
                  message: "Unable to decode the local Codex auth cache.",
                  cause,
                })
            )
          );
        }
      ),
    });
  }).pipe(Effect.withSpan("CodexLocalAuthCacheSourceLive"))
);

export const CodexLocalAuthCacheSourceMemory = (cache: unknown) =>
  Layer.succeed(CodexLocalAuthCacheSource, {
    readCache: () => decodeCodexCliAuthCache(cache),
  });

import {
  Config,
  Context,
  Duration,
  Effect,
  Layer,
  Option,
  Schema,
} from "effect";

import { CodexLocalProfileImportError } from "./errors.js";
import { CodexLocalProfileImportConfig } from "./schemas.js";
import type { CodexLocalProfileImportConfig as CodexLocalProfileImportConfigType } from "./schemas.js";

const localAuthFileConfig = Config.option(
  Config.schema(Schema.NonEmptyString, "BUNDJIL_CODEX_LOCAL_AUTH_FILE")
);

const homeDirectoryConfig = Config.option(Config.nonEmptyString("HOME"));

const principalIdConfig = Config.schema(
  Schema.NonEmptyString,
  "BUNDJIL_CODEX_PROFILE_PRINCIPAL_ID"
);

const connectorIdConfig = Config.schema(
  Schema.NonEmptyString.pipe(Schema.brand("CodexOAuthConnectorId")),
  "BUNDJIL_CODEX_PROFILE_CONNECTOR_ID"
);

const installationIdConfig = Config.schema(
  Schema.NonEmptyString.pipe(Schema.brand("CodexOAuthInstallationId")),
  "BUNDJIL_CODEX_PROFILE_INSTALLATION_ID"
);

const profileIdConfig = Config.schema(
  Schema.NonEmptyString.pipe(Schema.brand("CodexOAuthProfileId")),
  "BUNDJIL_CODEX_PROFILE_ID"
);

const accessTokenTtlConfig = Config.duration(
  "BUNDJIL_CODEX_LOCAL_ACCESS_TOKEN_TTL"
).pipe(Config.withDefault(Duration.hours(1)));

export class CodexLocalProfileImportConfigService extends Context.Service<
  CodexLocalProfileImportConfigService,
  CodexLocalProfileImportConfigType
>()("@bundjil/codex-oauth/CodexLocalProfileImportConfig") {}

export const loadCodexLocalProfileImportConfig = Effect.gen(
  function* loadCodexLocalProfileImportConfigFromProvider() {
    const configuredLocalAuthFile = yield* localAuthFileConfig;
    const homeDirectory = yield* homeDirectoryConfig;
    const principalId = yield* principalIdConfig;
    const connectorId = yield* connectorIdConfig;
    const installationId = yield* installationIdConfig;
    const profileId = yield* profileIdConfig;
    const accessTokenTtl = yield* accessTokenTtlConfig;

    const localAuthFile = Option.match(configuredLocalAuthFile, {
      onNone: () =>
        Option.match(homeDirectory, {
          onNone: () => undefined,
          onSome: (home) => `${home}/.codex/auth.json`,
        }),
      onSome: (path) => path,
    });

    return yield* Schema.decodeUnknownEffect(CodexLocalProfileImportConfig)({
      localAuthFile,
      subject: {
        provider: "codex",
        principal: {
          type: "chatgpt-user",
          id: principalId,
          issuer: "https://auth.openai.com",
        },
        connectorId,
        installationId,
        profileId,
      },
      accessTokenTtlMillis: Duration.toMillis(accessTokenTtl),
    }).pipe(
      Effect.mapError(
        (cause) =>
          new CodexLocalProfileImportError({
            operation: "loadConfig",
            message: "Unable to load local Codex profile import config.",
            cause,
          })
      )
    );
  }
).pipe(Effect.withSpan("CodexLocalProfileImportConfig.load"));

export const CodexLocalProfileImportConfigLive = Layer.effect(
  CodexLocalProfileImportConfigService,
  loadCodexLocalProfileImportConfig
);

import process from "node:process";

