import process from "node:process";

import { ConfigProvider, Effect, Exit, Schema } from "effect";

import {
  CodexLocalProfileImportResult,
  importCodexLocalProfile,
} from "../src/schemas.js";
import { CodexLocalAuthCacheSourceLive } from "../src/local-auth-cache-source.service.js";
import {
  CodexLocalProfileImportConfigLive,
} from "../src/local-profile-import.config.js";
import {
  CodexLocalProfileImportServiceLive,
  importCodexLocalProfile,
} from "../src/local-profile-import.service.js";
import {
  CodexOAuthProfileCipherConfigLive,
  CodexOAuthProfileCipherLive,
  CodexProfileStoreEncryptedKeyValueLive,
} from "../src/live.layer.js";
import { UpstashKeyValueStoreLive } from "../src/upstash-key-value-store.layer.js";

const program = importCodexLocalProfile.pipe(
  Effect.provide(CodexLocalProfileImportServiceLive),
  Effect.provide(CodexLocalAuthCacheSourceLive),
  Effect.provide(CodexLocalProfileImportConfigLive),
  Effect.provide(CodexProfileStoreEncryptedKeyValueLive),
  Effect.provide(CodexOAuthProfileCipherLive),
  Effect.provide(CodexOAuthProfileCipherConfigLive),
  Effect.provide(UpstashKeyValueStoreLive),
  Effect.provide(ConfigProvider.layer(ConfigProvider.fromEnv()))
);

const ImportSuccessOutput = Schema.Struct({
  status: Schema.Literal("imported"),
  result: CodexLocalProfileImportResult,
});

const ImportBlockedOutput = Schema.Struct({
  status: Schema.Literal("blocked"),
  message: Schema.NonEmptyString,
});

const encodeImportSuccessOutput = Schema.encodeSync(
  Schema.fromJsonString(ImportSuccessOutput)
);

const encodeImportBlockedOutput = Schema.encodeSync(
  Schema.fromJsonString(ImportBlockedOutput)
);

const exit = await Effect.runPromiseExit(program);

if (Exit.isSuccess(exit)) {
  process.stdout.write(
    `${encodeImportSuccessOutput({ status: "imported", result: exit.value })}\n`
  );
} else {
  process.stderr.write(
    `${encodeImportBlockedOutput({
      status: "blocked",
      message:
        "Codex local profile import requires valid local config, encrypted storage configuration, and a fresh ChatGPT-mode Codex login. No cache path, account id, token, or cache contents were printed.",
    })}\n`
  );
  process.exitCode = 1;
}
import { Context, Effect, Layer, Schema } from "effect";

import { CodexLocalProfileImportError } from "./errors.js";
import { CodexLocalProfileImportConfigService } from "./local-profile-import.config.js";
import { CodexCliAuthCache } from "./schemas.js";
import type { CodexCliAuthCache as CodexCliAuthCacheType } from "./schemas.js";

declare const Bun: {
  readonly file: (path: string) => {
    readonly text: () => Promise<string>;
  };
};

const codexCliAuthCacheJson = Schema.fromJsonString(CodexCliAuthCache);

const decodeCodexCliAuthCache = (input: unknown) =>
  Schema.decodeUnknownEffect(CodexCliAuthCache)(input).pipe(
    Effect.mapError(
      (cause) =>
        new CodexLocalProfileImportError({
          operation: "decodeCache",
          message: "Unable to decode the local Codex auth cache.",
          cause,
        })
    )
  );

export interface CodexLocalAuthCacheSourceShape {
  readonly readCache: () => Effect.Effect<
    CodexCliAuthCacheType,
    CodexLocalProfileImportError
  >;
}

export class CodexLocalAuthCacheSource extends Context.Service<
  CodexLocalAuthCacheSource,
  CodexLocalAuthCacheSourceShape
>()("@bundjil/codex-oauth/CodexLocalAuthCacheSource") {}

export const CodexLocalAuthCacheSourceLive = Layer.effect(
  CodexLocalAuthCacheSource,
  Effect.gen(function* makeCodexLocalAuthCacheSource() {
    const config = yield* CodexLocalProfileImportConfigService;

    return CodexLocalAuthCacheSource.of({
      readCache: Effect.fn("CodexLocalAuthCacheSource.readCache")(
        function* readCache() {
          const content = yield* Effect.tryPromise({
            try: () => Bun.file(config.localAuthFile).text(),
            catch: (cause) =>
              new CodexLocalProfileImportError({
                operation: "readCache",
                message: "Unable to read the local Codex auth cache.",
                cause,
              }),
          });

          return yield* Schema.decodeUnknownEffect(codexCliAuthCacheJson)(
            content
          ).pipe(
            Effect.mapError(
              (cause) =>
                new CodexLocalProfileImportError({
                  operation: "decodeCache",
                  message: "Unable to decode the local Codex auth cache.",
                  cause,
                })
            )
          );
        }
      ),
    });
  }).pipe(Effect.withSpan("CodexLocalAuthCacheSourceLive"))
);

export const CodexLocalAuthCacheSourceMemory = (cache: unknown) =>
  Layer.succeed(CodexLocalAuthCacheSource, {
    readCache: () => decodeCodexCliAuthCache(cache),
  });
