  `${String(value)} ${encodeUnknownJson(value)}`;

const makeAccessToken = Schema.decodeUnknownEffect(CodexResponsesPostInput)({
  accessToken: "codex-access-token-secret",
  request: {
    model: "gpt-5.5",
    input: [
